<script setup lang="ts">
import {computed,ref} from 'vue'
import {ArrowUpRight,RefreshCw,CheckCircle2,Activity,KeyRound,Sparkles} from 'lucide-vue-next'
import {cash,date,type Row} from '../lib'
import {useDashboard} from '../dashboard'
import DashboardOrders from './DashboardOrders.vue'
import './dashboard.css'
const props=defineProps<{user:Row}>()
const days=ref('7'),start=ref(''),end=ref(''),includeAdmin=ref(false),focus=ref(false),metric=ref('orders'),formError=ref('')
const query=ref('days=7'),path=computed(()=>'/admin/overview?'+query.value)
const {data,loading,error,refresh}=useDashboard(props.user.id,path)
function filter(){formError.value='';if(days.value==='custom'&&(!start.value||!end.value||start.value>end.value)){formError.value='请选择有效的开始和结束日期';return}const params=new URLSearchParams({days:days.value==='custom'?'7':days.value,include_admin:String(includeAdmin.value),focus:focus.value?'attention':'all'});if(days.value==='custom'){params.set('start',start.value);params.set('end',end.value)}query.value=params.toString()}
const todos=computed(()=>(data.value?.attention||[]).filter((r:Row)=>r.count>0))
const metrics=computed(()=>data.value?[{label:'新增订单',value:data.value.totals.orders,unit:'笔',hint:'期间创建的订阅 + 注册订单'},{label:'新增中已完成',value:data.value.totals.completed,unit:'笔',hint:`同批新增订单 · 另有 ${data.value.totals.partial} 笔部分交付`},{label:'净结算积分',value:cash(data.value.totals.settled),unit:'积分',hint:'实际扣费减退款，不含充值与调账'},{label:'当前待处理',value:data.value.totals.attention,unit:'项',hint:'全部时间 · 风险事件按全站统计'}]:[])
const chart=computed(()=>{
 const rows:Row[]=data.value?.trend||[],suffix=metric.value==='fees'?'_fees':''
 const max=Math.max(1,...rows.flatMap(r=>[Math.abs(Number(r['subscription'+suffix])),Math.abs(Number(r['registration'+suffix]))]))
 return rows.map(r=>({day:String(r.day),sub:Number(r['subscription'+suffix]),reg:Number(r['registration'+suffix]),subHeight:Math.abs(Number(r['subscription'+suffix]))/max*100,regHeight:Math.abs(Number(r['registration'+suffix]))/max*100}))
})
const signedChart=computed(()=>chart.value.some(p=>p.sub<0||p.reg<0))
const chartValue=(v:number)=>metric.value==='fees'?cash(v)+' 积分':v+' 笔'
</script>
<template><div class="dashboard admin-dashboard">
 <header class="dash-heading"><div><h1>运营概览</h1><p>先处理待办，再看业务与结算。</p></div><div class="dash-refresh"><small v-if="data">更新于 {{date(data.generated_at)}}</small><button class="btn secondary" :disabled="loading" @click="refresh" aria-label="刷新运营概览"><RefreshCw :size="15" :class="{spinning:loading}"/>刷新</button></div></header>
 <form class="dash-period" @submit.prevent="filter"><div class="dash-period-buttons" aria-label="统计日期"><button v-for="item in [{id:'1',label:'今天'},{id:'7',label:'近 7 天'},{id:'30',label:'近 30 天'},{id:'custom',label:'自定义'}]" type="button" :aria-pressed="days===item.id" :class="{active:days===item.id}" @click="days=item.id;if(days!=='custom')filter()">{{item.label}}</button></div><template v-if="days==='custom'"><label class="sr-only" for="dashboard-start">开始日期</label><input id="dashboard-start" v-model="start" type="date" required/><span>至</span><label class="sr-only" for="dashboard-end">结束日期</label><input id="dashboard-end" v-model="end" type="date" required/><button class="btn secondary" type="submit">应用</button></template><label class="dash-scope"><input type="checkbox" v-model="includeAdmin" @change="filter"/>包含管理员业务</label></form>
 <p v-if="data" class="dash-caption dash-range">{{data.start}} — {{data.end}} · 北京时间 · {{data.include_admin?'包含管理员':'默认只统计客户业务'}}；待办和队列显示当前状态</p>
 <div v-if="error||formError" class="alert danger" role="alert">{{data&&error?'刷新失败，当前显示上次数据。':''}}{{formError||error}}<button v-if="error" @click="refresh">重试</button></div>
 <div v-if="!data&&!error" class="dash-skeleton" aria-label="正在加载运营概览" :aria-busy="loading"><i/><i/><i/><i/></div>
 <template v-if="data"><section class="dash-metrics"><article v-for="item in metrics" :key="item.label" class="panel"><span>{{item.label}}</span><strong>{{item.value}}<small>{{item.unit}}</small></strong><p>{{item.hint}}</p></article></section>
 <section class="dash-section"><div class="dash-section-heading"><h2>待处理事项</h2><span class="dash-caption">不受统计日期影响</span></div><div v-if="todos.length" class="dash-todos"><a v-for="item in todos" :key="item.key" :href="item.href" class="dash-todo" :class="item.tone"><div><b>{{item.title}}</b><p>{{item.hint}}</p></div><strong>{{item.count}}<small>{{item.unit}}</small></strong><ArrowUpRight :size="16"/></a></div><div v-else class="dash-calm"><CheckCircle2 :size="19"/>当前没有待核查事项</div></section>
 <section class="dash-operations"><article v-for="business in ['registration','subscription']" :key="business" class="panel dash-operation"><div class="dash-section-heading"><h2><component :is="business==='registration'?KeyRound:Sparkles" :size="19"/>{{business==='registration'?'注册业务':'订阅业务'}}</h2><a :href="`#/admin/orders?business=${business}&include_admin=${data.include_admin}`" class="text-btn">查看订单<ArrowUpRight :size="14"/></a></div><div class="dash-operation-status"><span :class="data.queues[business].accepting?'positive':'muted'">{{data.queues[business].accepting?'已开放受理':'已关闭受理'}}</span><span>{{data.queues[business].paused?'队列已暂停':'队列调度已启用'}}</span></div><div class="dash-queue"><a :href="`#/admin/orders?business=${business}&include_admin=${data.include_admin}&status=queued`"><strong>{{data.queues[business].queued}}</strong><span>排队中 / 笔</span></a><a :href="`#/admin/orders?business=${business}&include_admin=${data.include_admin}&status=${business==='registration'?'running':'processing'}`"><strong>{{data.queues[business].running}}</strong><span>执行中 / 笔</span></a><a :href="`#/admin/orders?business=${business}&include_admin=${data.include_admin}&status=review`"><strong>{{data.queues[business].review}}</strong><span>待核实 / 笔</span></a></div><p class="dash-note">{{business==='registration'?`所选期间交付 ${data.queues.registration.delivered} 个账号，按实际交付结算。`:`另有 ${data.queues.subscription.settling} 笔已付款订单正在核实生效或处理续费。`}}</p></article></section>
 <section class="panel dash-section"><div class="dash-section-heading"><h2><Activity :size="18"/>业务趋势</h2><div class="dash-period-buttons"><button :class="{active:metric==='orders'}" :aria-pressed="metric==='orders'" @click="metric='orders'">新增订单</button><button :class="{active:metric==='fees'}" :aria-pressed="metric==='fees'" @click="metric='fees'">净结算积分</button></div></div><div class="dash-chart-legend"><span class="registration">注册</span><span class="subscription">订阅</span><small>{{metric==='fees'?'扣费 − 退款；负值表示当日净退款':'按创建日期统计，两类业务分别展示'}}</small></div><div class="dash-chart" :class="{'many-days':chart.length>31,signed:signedChart}" role="group" :aria-label="metric==='fees'?'每日净结算积分':'每日新增订单'"><div v-for="(point,index) in chart" :key="point.day" class="dash-chart-day" tabindex="0" :aria-label="`${point.day}，注册 ${chartValue(point.reg)}，订阅 ${chartValue(point.sub)}`"><div class="dash-chart-bars"><i class="registration" :class="{negative:point.reg<0}" :style="{height:point.regHeight/(signedChart?2:1)+'%'}"/><i class="subscription" :class="{negative:point.sub<0}" :style="{height:point.subHeight/(signedChart?2:1)+'%'}"/></div><span v-if="chart.length<15||index%Math.ceil(chart.length/8)===0">{{point.day.slice(5)}}</span><div class="dash-chart-tooltip">{{point.day}}<br/>注册 {{chartValue(point.reg)}}<br/>订阅 {{chartValue(point.sub)}}</div></div></div><p v-if="!chart.some(p=>p.sub||p.reg)" class="dash-chart-empty">这个时间范围还没有{{metric==='fees'?'结算':'新增订单'}}记录</p></section>
 <section class="panel dash-section"><div class="dash-section-heading"><h2>最近订单</h2><label class="dash-scope"><input type="checkbox" v-model="focus" @change="filter"/>只看需关注</label></div><p class="dash-caption">当前账户范围内最近 8 笔，跨日期跟进进度。</p><DashboardOrders :rows="data.recent_orders" admin :filtered="focus"/></section></template>
</div></template>
